def counting_sort(nums):
    if not nums:
        return nums
    count = [0] * (max(nums) + 1)
    for x in nums:
        count[x] += 1                     # how many times each value appears
    k = 0
    for v, c in enumerate(count):
        for _ in range(c):                # write each value back, count times
            nums[k] = v
            k += 1
    return nums

