function radixSort(nums) {
  const max = Math.max(0, ...nums);
  for (let exp = 1; Math.floor(max / exp) > 0; exp *= 10) {
    const buckets = Array.from({ length: 10 }, () => []);
    for (const x of nums) buckets[Math.floor(x / exp) % 10].push(x);   // stable: keep arrival order
    nums = buckets.flat();
  }
  return nums;
}

def radix_sort(nums):
    biggest = max(nums, default=0)
    exp = 1
    while biggest // exp > 0:
        buckets = [[] for _ in range(10)]
        for x in nums:
            buckets[x // exp % 10].append(x)   # stable: keep arrival order
        nums = [x for b in buckets for x in b]
        exp *= 10
    return nums

int[] radixSort(int[] nums) {
    int max = 0;
    for (int x : nums) max = Math.max(max, x);
    for (long exp = 1; max / exp > 0; exp *= 10) {
        List<List<Integer>> buckets = new ArrayList<>();
        for (int d = 0; d < 10; d++) buckets.add(new ArrayList<>());
        for (int x : nums) buckets.get((int) (x / exp % 10)).add(x);   // stable: keep arrival order
        int k = 0;
        for (List<Integer> b : buckets) for (int x : b) nums[k++] = x;
    }
    return nums;
}

vector<int> radixSort(vector<int> nums) {
    int mx = 0;
    for (int x : nums) mx = max(mx, x);
    for (long long exp = 1; mx / exp > 0; exp *= 10) {
        vector<vector<int>> buckets(10);
        for (int x : nums) buckets[x / exp % 10].push_back(x);   // stable: keep arrival order
        nums.clear();
        for (auto& b : buckets) nums.insert(nums.end(), b.begin(), b.end());
    }
    return nums;
}
